-- MODEL ( -- name datamart.daily_short_routes_cr, -- kind INCREMENTAL_BY_TIME_RANGE ( -- time_column doi -- ), -- start '2026-01-01', -- gateway athena, -- dialect athena, -- cron '@daily', -- table_format iceberg, -- partitioned_by doi -- ); /* Deduped Funnel Steps (1 row per session + route) */ WITH short_routes AS ( SELECT DISTINCT src_id, dest_id FROM lis.short_route_sds WHERE cohort = '2026' ), srp_deduped AS ( SELECT DISTINCT s.mri_session_id, s.route_id, s.rb_user_id, s.user_type, s.os, s.channel, s.src_id, s.dest_id, s.doj, CASE WHEN sr.src_id IS NOT NULL AND sr.dest_id IS NOT NULL THEN 'Short Routes' ELSE 'Long Routes' END AS route_type, DATE(DATE_TRUNC('DAY', AT_TIMEZONE(s.__time, 'Asia/Kolkata'))) AS doi, CAST(HOUR(AT_TIMEZONE(s.__time, 'Asia/Kolkata'))AS INT) AS day_hour FROM "user_interaction"."search_route_details" AS s LEFT JOIN short_routes sr ON s.src_id = sr.src_id AND s.dest_id = sr.dest_id WHERE s.__time >= DATE '2026-01-01' AND s.__time < DATE '2026-01-02' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND s.country = 'IND' AND s.status = 200 AND tp_channel = 'INVALID' AND akamai_bot IS NULL ), sl_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) AS rb_user_id FROM "user_interaction"."seat_layout_details" WHERE __time >= DATE '2026-01-01' AND __time < DATE '2026-01-02' AND country = 'IND' GROUP BY 1, 2 ), mpax_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) AS rb_user_id FROM "user_interaction"."cust_info_details" WHERE __time >= DATE '2026-01-01' AND __time < DATE '2026-01-02' AND country = 'IND' GROUP BY 1, 2 ), tco_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) AS rb_user_id FROM "user_interaction"."create_order_details" WHERE __time >= DATE '2026-01-01' AND __time < DATE '2026-01-02' AND country = 'IND' GROUP BY 1, 2 ), orderinfo_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) AS rb_user_id FROM "user_interaction"."order_info_details" WHERE __time >= DATE '2026-01-01' AND __time < DATE '2026-01-02' AND country = 'IND' GROUP BY 1, 2 ), addpay_deduped AS ( SELECT mri_session_id, MAX(rb_user_id) AS rb_user_id FROM "user_interaction"."make_payment_details" WHERE __time >= DATE '2026-01-01' AND __time < DATE '2026-01-02' AND country = 'IND' GROUP BY 1 ), confirm_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) AS rb_user_id, COUNT(DISTINCT tin) AS tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= DATE '2026-01-01' AND __time < DATE '2026-01-02' AND country = 'IND' AND status = 200 AND NOT tin IS NULL AND NOT tin IN ('', 'null') GROUP BY 1, 2 ) SELECT srp.doi, /* 'MTD Dec 28' AS month_period, */ UPPER(srp.user_type) AS user_type, srp.route_type, -- CAST(srp.src_id AS VARCHAR) ||'-'|| CAST(srp.dest_id AS VARCHAR) AS sd_id, -- src.location_name ||'-'|| dest.location_name AS route, CASE WHEN date_diff('day', srp.doi, srp.doj) = 0 AND srp.day_hour >= 17 THEN '0. LMB Same Day' WHEN date_diff('day', srp.doi, srp.doj) = 0 AND srp.day_hour < 17 THEN '0. non-LMB Same Day' WHEN date_diff('day', srp.doi, srp.doj) = 1 THEN '1. DBD 1' WHEN date_diff('day', srp.doi, srp.doj) = 2 THEN '2. DBD 2' WHEN date_diff('day', srp.doi, srp.doj) > 2 THEN '3. DBD 2+' ELSE 'NA' END AS dbd, CASE WHEN srp.os IS NULL THEN srp.channel ELSE srp.os END AS saleschannel, /* srp.route_type, */ COUNT(DISTINCT srp.mri_session_id) AS srpload, COUNT(DISTINCT sl.mri_session_id) AS slload, COUNT(DISTINCT pax.mri_session_id) AS CustInfoSession, COUNT(DISTINCT tco.mri_session_id) AS tcoload, COUNT(DISTINCT oi.mri_session_id) AS PaymentLandSessions, COUNT(DISTINCT ap.mri_session_id) AS AddPayClickSessions, COUNT(DISTINCT conf.mri_session_id) AS confirmsession, COUNT(DISTINCT srp.rb_user_id) AS srpUsers, COUNT(DISTINCT sl.rb_user_id) AS slUsers, COUNT(DISTINCT pax.rb_user_id) AS paxUsers, COUNT(DISTINCT tco.rb_user_id) AS tcoUsers, COUNT(DISTINCT oi.rb_user_id) AS orderinfoUsers, COUNT(DISTINCT conf.rb_user_id) AS confirmUsers, SUM(conf.tin_count) AS tin FROM srp_deduped AS srp LEFT JOIN "lis"."config_locations" src ON srp.src_id = src.id LEFT JOIN "lis"."config_locations" dest ON srp.dest_id = dest.id LEFT JOIN sl_deduped AS sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id LEFT JOIN mpax_deduped AS pax ON srp.mri_session_id = pax.mri_session_id AND srp.route_id = pax.route_id LEFT JOIN tco_deduped AS tco ON srp.mri_session_id = tco.mri_session_id AND srp.route_id = tco.route_id LEFT JOIN orderinfo_deduped AS oi ON srp.mri_session_id = oi.mri_session_id AND srp.route_id = oi.route_id LEFT JOIN addpay_deduped AS ap ON ap.mri_session_id = oi.mri_session_id LEFT JOIN confirm_deduped AS conf ON srp.mri_session_id = conf.mri_session_id AND srp.route_id = conf.route_id GROUP BY 1, 2, 3, 4, 5, 6, 7 UNION ALL SELECT srp.doi, /* 'MTD Dec 28' AS month_period, */ UPPER(srp.user_type) AS user_type, srp.route_type, CAST(srp.src_id AS VARCHAR) ||'-'|| CAST(srp.dest_id AS VARCHAR) AS sd_id, src.location_name ||'-'|| dest.location_name AS route, 'Overall' AS dbd, CASE WHEN srp.os IS NULL THEN srp.channel ELSE srp.os END AS saleschannel, /* srp.route_type, */ COUNT(DISTINCT srp.mri_session_id) AS srpload, COUNT(DISTINCT sl.mri_session_id) AS slload, COUNT(DISTINCT pax.mri_session_id) AS CustInfoSession, COUNT(DISTINCT tco.mri_session_id) AS tcoload, COUNT(DISTINCT oi.mri_session_id) AS PaymentLandSessions, COUNT(DISTINCT ap.mri_session_id) AS AddPayClickSessions, COUNT(DISTINCT conf.mri_session_id) AS confirmsession, COUNT(DISTINCT srp.rb_user_id) AS srpUsers, COUNT(DISTINCT sl.rb_user_id) AS slUsers, COUNT(DISTINCT pax.rb_user_id) AS paxUsers, COUNT(DISTINCT tco.rb_user_id) AS tcoUsers, COUNT(DISTINCT oi.rb_user_id) AS orderinfoUsers, COUNT(DISTINCT conf.rb_user_id) AS confirmUsers, SUM(conf.tin_count) AS tin FROM srp_deduped AS srp LEFT JOIN "lis"."config_locations" src ON srp.src_id = src.id LEFT JOIN "lis"."config_locations" dest ON srp.dest_id = dest.id LEFT JOIN sl_deduped AS sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id LEFT JOIN mpax_deduped AS pax ON srp.mri_session_id = pax.mri_session_id AND srp.route_id = pax.route_id LEFT JOIN tco_deduped AS tco ON srp.mri_session_id = tco.mri_session_id AND srp.route_id = tco.route_id LEFT JOIN orderinfo_deduped AS oi ON srp.mri_session_id = oi.mri_session_id AND srp.route_id = oi.route_id LEFT JOIN addpay_deduped AS ap ON ap.mri_session_id = oi.mri_session_id LEFT JOIN confirm_deduped AS conf ON srp.mri_session_id = conf.mri_session_id AND srp.route_id = conf.route_id GROUP BY 1, 2, 3, 4, 5, 6, 7
